            continue
        m = parse_movement_line(l, case_sizes)
        d, s, t, q = m["day"], m["sku"], m["type"], m["qty"]
        if d > today: continue
        if s not in earliest or d < earliest[s]: earliest[s] = d
        on_hand[s] = on_hand.get(s, 0) + q
        if t == "SHP":
            has_shp[s] = True
            if s not in last_shp or d > last_shp[s]: last_shp[s] = d
    res = []
    for s, qty in on_hand.items():
        if qty <= 0: continue
        if has_shp.get(s):
            if today - last_shp[s] >= idle_days: res.append(s)
        else:
            if today - earliest[s] >= idle_days: res.append(s)
    return sorted(res)"}}, "messages": []}

